1	import { createServer } from 'node:http';
2	import type { IncomingMessage, ServerResponse } from 'node:http';
3	import { mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs';
4	import { randomUUID } from 'node:crypto';
5	import { join } from 'node:path';
6	
7	const PRODUCT: string = 'QuillPress';
8	const RESOURCE: string = 'articles';
9	const MAX_BODY_BYTES: number = 5 * 1024 * 1024;
10	const PAGE: string = `<!doctype html>
11	<html lang="zh-CN">
12	<meta charset="utf-8">
13	<meta name="viewport" content="width=device-width,initial-scale=1">
14	<title>QuillPress · 内容编辑与刊物发布</title>
15	<style>
16	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7;color:#1f2328}
17	a{color:#175b9c}
18	h2{margin-top:2rem}
19	form{border:1px solid #d0d7de;border-radius:8px;padding:1rem 1.25rem;margin:1rem 0 1.5rem}
20	form.editing{border-color:#175b9c;box-shadow:0 0 0 2px rgba(23,91,156,.15)}
21	label{display:block;font-weight:600;margin:.9rem 0 .3rem}
22	input[type=text],textarea{width:100%;box-sizing:border-box;font:inherit;padding:.5rem .6rem;border:1px solid #d0d7de;border-radius:6px;background:#fff;color:inherit}
23	textarea{resize:vertical}
24	button{margin-top:1.1rem;font:inherit;padding:.5rem 1.3rem;border-radius:6px;border:1px solid #175b9c;background:#175b9c;color:#fff;cursor:pointer}
25	button.secondary{background:#fff;color:#175b9c;margin-left:.6rem}
26	button:disabled{opacity:.55;cursor:default}
27	button.danger{border-color:#c0392b;background:#fff;color:#c0392b}
28	.status{margin:.8rem 0 0;min-height:1.4em}
29	.status.ok{color:#1a7f37}.status.err{color:#c0392b}.status.warn{color:#8a5a00}
30	.edit-banner{margin:0 0 .25rem;padding:.6rem .8rem;border-radius:6px;background:#eef4fb;border:1px solid #b6d2ee;color:#14467a;font-size:.92rem}
31	.edit-banner code{background:#dde9f6;padding:0 .3rem;border-radius:3px}
32	.edit-banner .meta{color:#3d6391;font-size:.85rem;margin-top:.2rem}
33	ul.articles{list-style:none;padding:0;margin:0}
34	article.draft{border:1px solid #d0d7de;border-radius:8px;padding:1rem 1.25rem;margin:1rem 0}
35	article.draft.editing{border-color:#175b9c;box-shadow:0 0 0 2px rgba(23,91,156,.15)}
36	.draft h3{margin:0 0 .4rem;word-break:break-word}
37	.draft .meta{color:#656d76;font-size:.85rem;margin:0 0 .5rem}
38	.draft .summary{white-space:pre-wrap;word-break:break-word;margin:0 0 .4rem;color:#3a4149}
39	.draft .actions{margin:.6rem 0 0}
40	.draft .actions button{margin:0;padding:.3rem .9rem;font-size:.88rem}
41	.draft .editing-tag{margin-left:.5rem;font-size:.78rem;font-weight:600;color:#175b9c;border:1px solid #175b9c;border-radius:999px;padding:0 .55rem;vertical-align:middle}
42	.empty{color:#656d76}
43	.empty.err{color:#c0392b}
44	.conflict{margin-top:1rem;border:1px solid #d9a441;border-radius:8px;background:#fffaf0;padding:1rem 1.25rem}
45	.conflict h3{margin:0 0 .3rem;color:#8a5a00;font-size:1.05rem}
46	.conflict .conflict-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:.7rem}
47	@media (max-width:46rem){.conflict .conflict-grid{grid-template-columns:1fr}}
48	.conflict .ver{border:1px solid #d0d7de;border-radius:6px;padding:.7rem .85rem;background:#fff;min-width:0}
49	.conflict .ver.saved{border-color:#8ab46a;background:#f6fbf2}
50	.conflict .ver h4{margin:0 0 .5rem;font-size:.92rem}
51	.conflict .ver dl{margin:0}
52	.conflict .ver dt{font-weight:600;font-size:.82rem;color:#57606a;margin-top:.5rem}
53	.conflict .ver dt:first-child{margin-top:0}
54	.conflict .ver dd{margin:.15rem 0 0;white-space:pre-wrap;word-break:break-word;font-size:.88rem;background:#f6f8fa;border-radius:4px;padding:.35rem .5rem;max-height:12rem;overflow:auto}
55	.conflict .ver.saved dd{background:#eef5e8}
56	.conflict .ver dd.empty-field{color:#8a8f98;font-style:italic;background:transparent;padding:0}
57	.conflict .actions{margin-top:.8rem}
58	.conflict .actions button{margin-top:0}
59	.conflict .actions .tip{font-size:.82rem;color:#8a5a00;margin-left:.6rem}
60	</style>
61	<main>
62	<h1>QuillPress</h1>
63	<p>内容编辑与刊物发布</p>
64	
65	<section aria-labelledby="compose-heading">
66	<h2 id="compose-heading">保存草稿</h2>
67	<form id="draft-form" autocomplete="off">
68	  <div id="edit-banner" class="edit-banner" hidden></div>
69	  <label for="title">标题</label>
70	  <input id="title" name="title" type="text">
71	  <label for="summary">摘要（可选）</label>
72	  <textarea id="summary" name="summary" rows="3"></textarea>
73	  <label for="body">正文</label>
74	  <textarea id="body" name="body" rows="10"></textarea>
75	  <button id="save-btn" type="submit">保存草稿</button>
76	  <button id="cancel-btn" class="secondary" type="button" hidden>取消编辑</button>
77	  <p id="status" class="status" role="status" aria-live="polite"></p>
78	  <div id="conflict-box" class="conflict" hidden></div>
79	</form>
80	</section>
81	
82	<section aria-labelledby="list-heading">
83	<h2 id="list-heading">草稿列表</h2>
84	<ul id="article-list" class="articles"></ul>
85	<p id="empty-tip" class="empty">草稿加载中…</p>
86	</section>
87	
88	<p><a href="/api/articles">查看文章列表接口</a> · <a href="/health">服务状态</a></p>
89	</main>
90	<script>
91	(function () {
92	  'use strict';
93	  var form = document.getElementById('draft-form');
94	  var titleInput = document.getElementById('title');
95	  var summaryInput = document.getElementById('summary');
96	  var bodyInput = document.getElementById('body');
97	  var saveBtn = document.getElementById('save-btn');
98	  var cancelBtn = document.getElementById('cancel-btn');
99	  var statusEl = document.getElementById('status');
100	  var editBanner = document.getElementById('edit-banner');
101	  var conflictBox = document.getElementById('conflict-box');
102	  var listEl = document.getElementById('article-list');
103	  var emptyTip = document.getElementById('empty-tip');
104	  var articles = [];
105	  var saving = false;
106	  // null = 新建草稿模式；对象 = 正在编辑的服务端版本 {id,title,summary,body,version}
107	  var editing = null;
108	
109	  function setStatus(text, kind) {
110	    statusEl.textContent = text || '';
111	    statusEl.className = 'status' + (kind ? ' ' + kind : '');
112	  }
113	  function setEmpty(text, kind) {
114	    emptyTip.textContent = text || '';
115	    emptyTip.className = 'empty' + (kind ? ' ' + kind : '');
116	    emptyTip.hidden = !text;
117	  }
118	  function hideConflict() {
119	    conflictBox.hidden = true;
120	    conflictBox.textContent = '';
121	  }
122	  function formatTime(iso) {
123	    var d = new Date(iso);
124	    return isNaN(d.getTime()) ? String(iso) : d.toLocaleString();
125	  }
126	  function render() {
127	    var sorted = articles.slice().sort(function (a, b) {
128	      var ta = a && a.createdAt ? String(a.createdAt) : '';
129	      var tb = b && b.createdAt ? String(b.createdAt) : '';
130	      if (ta !== tb) return ta < tb ? 1 : -1;
131	      return 0;
132	    });
133	    listEl.textContent = '';
134	    sorted.forEach(function (article) {
135	      var isEditing = editing && editing.id === article.id;
136	      var card = document.createElement('article');
137	      card.className = 'draft' + (isEditing ? ' editing' : '');
138	      var h = document.createElement('h3');
139	      h.textContent = article.title == null ? '' : String(article.title);
140	      if (isEditing) {
141	        var tag = document.createElement('span');
142	        tag.className = 'editing-tag';
143	        tag.textContent = '编辑中';
144	        h.appendChild(tag);
145	      }
146	      var meta = document.createElement('p');
147	      meta.className = 'meta';
148	      meta.textContent = '创建时间：' + formatTime(article.createdAt);
149	      var summary = document.createElement('p');
150	      summary.className = 'summary';
151	      var summaryText = article.summary == null ? '' : String(article.summary);
152	      summary.textContent = summaryText;
153	      card.appendChild(h);
154	      card.appendChild(meta);
155	      if (summaryText) card.appendChild(summary);
156	      var actions = document.createElement('p');
157	      actions.className = 'actions';
158	      var editBtn = document.createElement('button');
159	      editBtn.type = 'button';
160	      editBtn.className = 'secondary';
161	      editBtn.textContent = isEditing ? '正在编辑' : '编辑';
162	      editBtn.disabled = !!isEditing;
163	      editBtn.addEventListener('click', function () { startEdit(article.id); });
164	      actions.appendChild(editBtn);
165	      card.appendChild(actions);
166	      var li = document.createElement('li');
167	      li.appendChild(card);
168	      listEl.appendChild(li);
169	    });
170	    setEmpty(sorted.length === 0 ? '还没有保存的草稿。' : '');
171	  }
172	  function load() {
173	    return fetch('/api/articles', { headers: { accept: 'application/json' } })
174	      .then(function (r) {
175	        if (!r.ok) throw new Error('HTTP ' + r.status);
176	        return r.json();
177	      })
178	      .then(function (data) {
179	        articles = data && Array.isArray(data.articles) ? data.articles : [];
180	        render();
181	      })
182	      .catch(function (err) {
183	        articles = [];
184	        listEl.textContent = '';
185	        setEmpty('草稿列表加载失败：' + (err && err.message ? err.message : err), 'err');
186	      });
187	  }
188	
189	  function setSaving(on, label) {
190	    saving = on;
191	    saveBtn.disabled = on;
192	    saveBtn.textContent = label || (editing ? '保存修改' : '保存草稿');
193	    cancelBtn.disabled = on;
194	  }
195	
196	  function enterCreateMode(message, kind) {
197	    editing = null;
198	    form.reset();
199	    form.classList.remove('editing');
200	    editBanner.hidden = true;
201	    editBanner.textContent = '';
202	    hideConflict();
203	    cancelBtn.hidden = true;
204	    saveBtn.textContent = '保存草稿';
205	    setStatus(message || '', kind || '');
206	    render();
207	  }
208	
209	  function renderEditBanner(article) {
210	    editBanner.textContent = '';
211	    var line1 = document.createElement('div');
212	    line1.textContent = '正在编辑草稿：';
213	    var code = document.createElement('code');
214	    code.textContent = String(article.title);
215	    line1.appendChild(code);
216	    var line2 = document.createElement('div');
217	    line2.className = 'meta';
218	    line2.textContent = '创建时间：' + formatTime(article.createdAt) + ' · 标识：' + String(article.id);
219	    editBanner.appendChild(line1);
220	    editBanner.appendChild(line2);
221	  }
222	
223	  function applyEditingState(article) {
224	    editing = {
225	      id: article.id,
226	      title: article.title,
227	      summary: article.summary,
228	      body: article.body,
229	      version: article.version
230	    };
231	    titleInput.value = article.title == null ? '' : String(article.title);
232	    summaryInput.value = article.summary == null ? '' : String(article.summary);
233	    bodyInput.value = article.body == null ? '' : String(article.body);
234	    form.classList.add('editing');
235	    renderEditBanner(article);
236	    editBanner.hidden = false;
237	    cancelBtn.hidden = false;
238	    saveBtn.textContent = '保存修改';
239	    hideConflict();
240	    setStatus('已载入该草稿当前保存的内容，可以开始修改。', null);
241	    render();
242	    titleInput.focus();
243	  }
244	
245	  function isDirty() {
246	    if (!editing) {
247	      return titleInput.value !== '' || summaryInput.value !== '' || bodyInput.value !== '';
248	    }
249	    return titleInput.value !== editing.title
250	      || summaryInput.value !== editing.summary
251	      || bodyInput.value !== editing.body;
252	  }
253	
254	  function startEdit(id) {
255	    if (saving) return;
256	    if (isDirty() && !window.confirm('当前表单有未保存的修改，打开另一篇草稿将放弃这些输入。确定继续吗？')) {
257	      return;
258	    }
259	    setSaving(true, '读取中…');
260	    setStatus('正在读取草稿内容…', null);
261	    fetch('/api/articles/' + encodeURIComponent(id), { headers: { accept: 'application/json' } })
262	      .then(function (r) {
263	        return r.json().catch(function () { return null; }).then(function (data) {
264	          if (!r.ok || !data || !data.article) {
265	            throw new Error(data && data.error ? data.error : ('HTTP ' + r.status));
266	          }
267	          return data.article;
268	        });
269	      })
270	      .then(function (article) {
271	        setSaving(false);
272	        // 正文必须来自单篇接口，绝不使用列表里的摘要充当正文
273	        applyEditingState(article);
274	      })
275	      .catch(function (err) {
276	        setSaving(false);
277	        saveBtn.textContent = editing ? '保存修改' : '保存草稿';
278	        setStatus('打开草稿失败：' + (err && err.message ? err.message : err) + '，可稍后重试。', 'err');
279	      });
280	  }
281	
282	  cancelBtn.addEventListener('click', function () {
283	    if (saving || !editing) return;
284	    // 取消不提交任何修改，也不删除原文章，直接回到新建草稿状态
285	    if (isDirty() && !window.confirm('取消将放弃当前未保存的修改，原草稿不会被删除。确定取消编辑吗？')) {
286	      return;
287	    }
288	    enterCreateMode('已取消编辑，原草稿未改动。可以新建草稿。', null);
289	  });
290	
291	  function fieldValue(text, isEmpty) {
292	    var dd = document.createElement('dd');
293	    if (isEmpty) {
294	      dd.className = 'empty-field';
295	      dd.textContent = '（空）';
296	    } else {
297	      dd.textContent = text;
298	    }
299	    return dd;
300	  }
301	
302	  function showConflict(saved) {
303	    // 只展示对照，绝不重置表单、绝不自动重试覆盖
304	    conflictBox.textContent = '';
305	    var h = document.createElement('h3');
306	    h.textContent = '检测到较新的已保存内容';
307	    var p = document.createElement('p');
308	    p.textContent = '这篇草稿在其他页面已被修改并保存。为避免覆盖新版本，本次保存已被拒绝。你输入的内容仍保留在上方表单中，可对照右侧最新版本；只有明确放弃当前输入后，才会载入最新内容继续编辑。';
309	    conflictBox.appendChild(h);
310	    conflictBox.appendChild(p);
311	
312	    var grid = document.createElement('div');
313	    grid.className = 'conflict-grid';
314	
315	    var mine = document.createElement('div');
316	    mine.className = 'ver mine';
317	    var mineTitle = document.createElement('h4');
318	    mineTitle.textContent = '你正在编辑的内容（未保存）';
319	    mine.appendChild(mineTitle);
320	    var dl1 = document.createElement('dl');
321	    [['标题', titleInput.value, titleInput.value.trim() === ''],
322	     ['摘要', summaryInput.value, summaryInput.value === ''],
323	     ['正文', bodyInput.value, bodyInput.value === '']].forEach(function (pair) {
324	      var dt = document.createElement('dt');
325	      dt.textContent = pair[0];
326	      dl1.appendChild(dt);
327	      dl1.appendChild(fieldValue(pair[1], pair[2]));
328	    });
329	    mine.appendChild(dl1);
330	
331	    var theirs = document.createElement('div');
332	    theirs.className = 'ver saved';
333	    var tTitle = document.createElement('h4');
334	    tTitle.textContent = '最新已保存内容';
335	    theirs.appendChild(tTitle);
336	    var dl2 = document.createElement('dl');
337	    [['标题', saved.title, saved.title === ''],
338	     ['摘要', saved.summary, saved.summary === ''],
339	     ['正文', saved.body, saved.body === '']].forEach(function (pair) {
340	      var dt = document.createElement('dt');
341	      dt.textContent = pair[0];
342	      dl2.appendChild(dt);
343	      dl2.appendChild(fieldValue(pair[1], pair[2]));
344	    });
345	    theirs.appendChild(dl2);
346	
347	    grid.appendChild(mine);
348	    grid.appendChild(theirs);
349	    conflictBox.appendChild(grid);
350	
351	    var actions = document.createElement('p');
352	    actions.className = 'actions';
353	    var discard = document.createElement('button');
354	    discard.type = 'button';
355	    discard.className = 'danger';
356	    discard.textContent = '放弃当前输入并载入最新内容';
357	    discard.addEventListener('click', function () {
358	      applyEditingState(saved);
359	    });
360	    var keep = document.createElement('button');
361	    keep.type = 'button';
362	    keep.className = 'secondary';
363	    keep.textContent = '保留我的输入，继续修改';
364	    keep.addEventListener('click', function () {
365	      hideConflict();
366	      setStatus('已保留你的输入，请对照后手动调整再保存。', null);
367	      titleInput.focus();
368	    });
369	    var tip = document.createElement('span');
370	    tip.className = 'tip';
371	    tip.textContent = '不会自动覆盖或重置。';
372	    actions.appendChild(discard);
373	    actions.appendChild(keep);
374	    actions.appendChild(tip);
375	    conflictBox.appendChild(actions);
376	    conflictBox.hidden = false;
377	  }
378	
379	  form.addEventListener('submit', function (event) {
380	    event.preventDefault();
381	    if (saving) return;
382	    var trimmedTitle = titleInput.value.trim();
383	    if (!trimmedTitle) {
384	      setStatus('标题不能为空。', 'err');
385	      titleInput.focus();
386	      return;
387	    }
388	    hideConflict();
389	    var isEdit = !!editing;
390	    // 记录本次实际提交的原始字段值，响应返回时据此判断等待期间哪些字段又被编辑过。
391	    var submitted = {
392	      title: titleInput.value,
393	      summary: summaryInput.value,
394	      body: bodyInput.value
395	    };
396	    var payload = {
397	      title: titleInput.value,
398	      summary: summaryInput.value,
399	      body: bodyInput.value
400	    };
401	    var url = '/api/articles';
402	    if (isEdit) {
403	      url += '/' + encodeURIComponent(editing.id);
404	      payload.version = editing.version;
405	    }
406	    setSaving(true, '保存中…');
407	    setStatus(isEdit ? '正在保存修改…' : '正在保存…', null);
408	    fetch(url, {
409	      method: isEdit ? 'PUT' : 'POST',
410	      headers: { 'content-type': 'application/json', accept: 'application/json' },
411	      body: JSON.stringify(payload)
412	    })
413	      .then(function (r) {
414	        return r.json().catch(function () { return null; }).then(function (data) {
415	          return { status: r.status, data: data };
416	        });
417	      })
418	      .then(function (result) {
419	        var data = result.data;
420	        if (result.status === 409 && data && data.article) {
421	          // 版本冲突：保留表单全部输入，展示最新已保存内容供对照。
422	          // 绝不更新本地基准版本——只有用户显式确认载入最新内容后才允许覆盖。
423	          setSaving(false);
424	          saveBtn.textContent = editing ? '保存修改' : '保存草稿';
425	          setStatus('保存被拒绝：存在较新的已保存版本（409）。请对照后选择保留输入或载入最新内容。', 'err');
426	          showConflict(data.article);
427	          return;
428	        }
429	        if (result.status < 200 || result.status >= 300 || !data || !data.article) {
430	          throw new Error(data && data.error ? data.error : ('HTTP ' + result.status));
431	        }
432	        return data.article;
433	      })
434	      .then(function (article) {
435	        if (!article) return; // 冲突分支已处理
436	        if (isEdit) {
437	          var idx = -1;
438	          for (var i = 0; i < articles.length; i++) {
439	            if (articles[i] && articles[i].id === article.id) { idx = i; break; }
440	          }
441	          if (idx >= 0) articles[idx] = article; else articles.push(article);
442	          render();
443	          setSaving(false);
444	          // 保持编辑态：仍是同一篇草稿，可继续修改。
445	          // 成功只确认本次提交的内容；等待响应期间补写的字段原样保留，不被覆盖。
446	          mergeSavedEditingState(article, submitted);
447	        } else {
448	          // 新建成功：列表只显示本次实际保存的内容。若等待响应期间表单又被改过
449	          // 且未恢复为保存值，绝不能清空这些输入——把表单关联到刚创建的同一篇
450	          // 草稿进入编辑态，后续“保存修改”按本次响应的版本更新它，不再新建。
451	          articles.push(article);
452	          setSaving(false);
453	          if (hasUnsavedAfterSave(article, submitted)) {
454	            mergeSavedEditingState(article, submitted, true);
455	          } else {
456	            enterCreateMode('草稿已保存。可以继续新建草稿。', 'ok');
457	          }
458	        }
459	      })
460	      .catch(function (err) {
461	        setSaving(false);
462	        saveBtn.textContent = editing ? '保存修改' : '保存草稿';
463	        var prefix = isEdit ? '保存修改失败：' : '保存失败：';
464	        setStatus(prefix + (err && err.message ? err.message : err) + '，输入已保留，可处理后再次操作。', 'err');
465	      });
466	  });
467	
468	  function savedFieldList(article) {
469	    return [
470	      { key: 'title', label: '标题', el: titleInput, value: article.title == null ? '' : String(article.title) },
471	      { key: 'summary', label: '摘要', el: summaryInput, value: article.summary == null ? '' : String(article.summary) },
472	      { key: 'body', label: '正文', el: bodyInput, value: article.body == null ? '' : String(article.body) }
473	    ];
474	  }
475	
476	  // 是否仍有未保存内容，以当前表单与本次成功保存的内容是否相同为准：
477	  // 字段仍等于提交快照，或被改过又恢复为服务端保存值（如去首尾空白后的标题），
478	  // 都视为没有未保存修改。
479	  function hasUnsavedAfterSave(article, submitted) {
480	    return savedFieldList(article).some(function (f) {
481	      return f.el.value !== submitted[f.key] && f.el.value !== f.value;
482	    });
483	  }
484	
485	  // 保存成功后留在编辑态。成功响应只能确认本次提交的内容：
486	  // 服务端返回的已保存内容成为新的本地基准（version 一并推进，再次保存不会误报冲突），
487	  // 但等待响应期间用户继续输入过的字段必须保留当前值（含换行、空行与清空操作），
488	  // 绝不能用刚保存的旧值回填或替换。isCreate 表示这是新建草稿后的首次关联。
489	  function mergeSavedEditingState(article, submitted, isCreate) {
490	    var savedFields = savedFieldList(article);
491	    var editedWhileSaving = [];
492	    savedFields.forEach(function (f) {
493	      if (f.el.value === submitted[f.key]) {
494	        // 等待期间未再改动：同步为服务端保存的规范值（例如去首尾空白后的标题）。
495	        if (f.el.value !== f.value) f.el.value = f.value;
496	      } else {
497	        // 等待期间又被修改（包括清空摘要或正文）：保留当前输入，不动一个字符。
498	        // 仅当保留下来的当前值确实与本次已保存值不同时，才算仍有未保存修改。
499	        if (f.el.value !== f.value) editedWhileSaving.push(f.label);
500	      }
501	    });
502	    editing = {
503	      id: article.id,
504	      title: savedFields[0].value,
505	      summary: savedFields[1].value,
506	      body: savedFields[2].value,
507	      version: article.version
508	    };
509	    form.classList.add('editing');
510	    renderEditBanner(article);
511	    editBanner.hidden = false;
512	    cancelBtn.hidden = false;
513	    saveBtn.textContent = '保存修改';
514	    hideConflict();
515	    render();
516	    if (editedWhileSaving.length === 0) {
517	      setStatus(isCreate
518	        ? '草稿已保存。可以继续修改，也可以取消编辑后新建下一篇。'
519	        : '修改已保存。文章标识、创建时间与草稿状态均未改变。', 'ok');
520	    } else if (isCreate) {
521	      setStatus('本次提交的草稿已保存，列表显示的是实际保存的内容。但'
522	        + editedWhileSaving.join('、')
523	        + '在保存期间又被修改，这些新输入尚未保存；表单已关联到刚创建的这篇草稿，再次点击“保存修改”将更新同一篇。', 'warn');
524	    } else {
525	      setStatus('本次提交的内容已保存（文章标识、创建时间与草稿状态不变）。但'
526	        + editedWhileSaving.join('、')
527	        + '在保存期间又被修改，这些新输入尚未保存；再次点击“保存修改”才会一并存入同一篇草稿。', 'warn');
528	    }
529	  }
530	
531	  load();
532	})();
533	</script>
534	</html>`;
535	const args: string[] = process.argv.slice(2);
536	const help: string = `QuillPress - 内容编辑与刊物发布
537	Usage: node server.ts serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]
538	       node server.ts --help
539	Defaults: --host 127.0.0.1 --port 8080 --data-dir data
540	Port 0 selects an available port.
541	`;
542	if (args.length === 0 || args.includes('--help') || args.includes('-h')) {
543	  process.stdout.write(help);
544	  process.exit(args.length === 0 ? 2 : 0);
545	}
546	if (args.shift() !== 'serve') { console.error('Expected serve or --help'); process.exit(2); }
547	let host: string = '127.0.0.1';
548	let port: number = 8080;
549	let dataDir: string = 'data';
550	while (args.length) {
551	  const flag = args.shift();
552	  const value = args.shift();
553	  if (!value || !['--host', '--port', '--data-dir'].includes(flag ?? '')) {
554	    console.error('Each option must be --host, --port or --data-dir followed by a value'); process.exit(2);
555	  }
556	  if (flag === '--host') host = value;
557	  else if (flag === '--port') {
558	    if (!/^\d+$/.test(value) || Number(value) > 65535) { console.error('Port must be between 0 and 65535'); process.exit(2); }
559	    port = Number(value);
560	  } else dataDir = value;
561	}
562	mkdirSync(dataDir, { recursive: true });
563	const dataFile = join(dataDir, 'articles.json');
564	try { writeFileSync(dataFile, '[]\n', { flag: 'wx' }); } catch (error) {
565	  if (!(error instanceof Error && 'code' in error && error.code === 'EEXIST')) throw error;
566	}
567	
568	interface Article {
569	  id: string;
570	  title: string;
571	  summary: string;
572	  body: string;
573	  status: 'draft';
574	  createdAt: string;
575	  version: number;
576	}
577	interface StoredArticle {
578	  id?: unknown;
579	  title?: unknown;
580	  summary?: unknown;
581	  body?: unknown;
582	  status?: unknown;
583	  createdAt?: unknown;
584	  version?: unknown;
585	}
586	interface DraftInput {
587	  title: string;
588	  summary: string;
589	  body: string;
590	}
591	
592	class HttpError extends Error {
593	  status: number;
594	  constructor(status: number, message: string) {
595	    super(message);
596	    this.name = 'HttpError';
597	    this.status = status;
598	  }
599	}
600	
601	function respond(res: ServerResponse, status: number, value: unknown, html = false): void {
602	  const body = html ? String(value) : JSON.stringify(value);
603	  res.writeHead(status, {
604	    'content-type': html ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
605	    'content-length': Buffer.byteLength(body),
606	  });
607	  res.end(body);
608	}
609	
610	function methodNotAllowed(res: ServerResponse, allow: string): void {
611	  const body = JSON.stringify({ error: 'method not allowed' });
612	  res.writeHead(405, {
613	    'content-type': 'application/json; charset=utf-8',
614	    'content-length': Buffer.byteLength(body),
615	    allow,
616	  });
617	  res.end(body);
618	}
619	
620	// Normalize a stored record. Drafts saved by older versions have no `version`
621	// field; those are treated as version 0 and can be opened and edited directly.
622	function normalizeArticle(record: unknown): Article | null {
623	  if (typeof record !== 'object' || record === null || Array.isArray(record)) return null;
624	  const r = record as StoredArticle;
625	  if (typeof r.id !== 'string' || typeof r.title !== 'string' || typeof r.body !== 'string') return null;
626	  if (r.status !== 'draft' || typeof r.createdAt !== 'string') return null;
627	  const version = typeof r.version === 'number' && Number.isInteger(r.version) && r.version >= 0 ? r.version : 0;
628	  return {
629	    id: r.id,
630	    title: r.title,
631	    summary: typeof r.summary === 'string' ? r.summary : '',
632	    body: r.body,
633	    status: 'draft',
634	    createdAt: r.createdAt,
635	    version,
636	  };
637	}
638	
639	function readArticles(): Article[] {
640	  let parsed: unknown;
641	  try {
642	    parsed = JSON.parse(readFileSync(dataFile, 'utf8'));
643	  } catch (error) {
644	    throw new Error(`unable to read articles: ${(error as Error).message}`);
645	  }
646	  if (!Array.isArray(parsed)) throw new Error('unable to read articles: stored data is not a list');
647	  const articles: Article[] = [];
648	  for (const record of parsed) {
649	    const article = normalizeArticle(record);
650	    if (article) articles.push(article);
651	  }
652	  return articles;
653	}
654	
655	function writeArticles(records: Article[]): void {
656	  const tmpFile = join(dataDir, `.articles.${process.pid}.tmp`);
657	  try {
658	    writeFileSync(tmpFile, `${JSON.stringify(records, null, 2)}\n`);
659	    renameSync(tmpFile, dataFile);
660	  } catch (error) {
661	    try { rmSync(tmpFile, { force: true }); } catch { /* best effort cleanup */ }
662	    throw new Error(`unable to save articles: ${(error as Error).message}`);
663	  }
664	}
665	
666	// Serialize read-modify-write so concurrent saves never lose or corrupt records.
667	let writeQueue: Promise<void> = Promise.resolve();
668	function enqueueWrite<T>(task: () => T): Promise<T> {
669	  const run = writeQueue.then(task);
670	  writeQueue = run.then(() => undefined, () => undefined);
671	  return run;
672	}
673	
674	function readBody(req: IncomingMessage): Promise<string> {
675	  return new Promise((resolve, reject) => {
676	    const chunks: Buffer[] = [];
677	    let size = 0;
678	    let settled = false;
679	    req.on('data', (chunk: unknown) => {
680	      if (settled) return;
681	      const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk));
682	      size += buf.length;
683	      if (size > MAX_BODY_BYTES) {
684	        settled = true;
685	        reject(new HttpError(400, 'request body is too large'));
686	        req.destroy();
687	        return;
688	      }
689	      chunks.push(buf);
690	    });
691	    req.on('end', () => {
692	      if (!settled) resolve(Buffer.concat(chunks).toString('utf8'));
693	    });
694	    req.on('error', (error: Error) => {
695	      if (!settled) reject(new HttpError(400, `could not read request body: ${error.message}`));
696	    });
697	  });
698	}
699	
700	function parseJsonObject(text: string): Record<string, unknown> {
701	  let payload: unknown;
702	  try {
703	    payload = JSON.parse(text);
704	  } catch (error) {
705	    throw new HttpError(400, `invalid JSON: ${(error as Error).message}`);
706	  }
707	  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
708	    throw new HttpError(400, 'request body must be a JSON object');
709	  }
710	  return payload as Record<string, unknown>;
711	}
712	
713	function validateDraftInput(data: Record<string, unknown>): DraftInput {
714	  if (typeof data.title !== 'string') {
715	    throw new HttpError(400, 'title must be a string');
716	  }
717	  const title = data.title.trim();
718	  if (title.length === 0) {
719	    throw new HttpError(400, 'title must not be empty or only whitespace');
720	  }
721	  let summary = '';
722	  if (Object.prototype.hasOwnProperty.call(data, 'summary')) {
723	    if (typeof data.summary !== 'string') throw new HttpError(400, 'summary must be a string when provided');
724	    summary = data.summary;
725	  }
726	  if (typeof data.body !== 'string') {
727	    throw new HttpError(400, 'body must be a string');
728	  }
729	  return { title, summary, body: data.body };
730	}
731	
732	// Updates carry the version the editor loaded; stale versions are rejected.
733	// As with creation, summary may be omitted (saved as empty string) but a
734	// present non-string summary is a 400.
735	function validateUpdateInput(data: Record<string, unknown>): DraftInput & { version: number } {
736	  const fields = validateDraftInput(data);
737	  if (typeof data.version !== 'number' || !Number.isInteger(data.version) || data.version < 0) {
738	    throw new HttpError(400, 'version must be a non-negative integer');
739	  }
740	  return { ...fields, version: data.version };
741	}
742	
743	async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
744	  let route: string;
745	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; }
746	  catch { respond(res, 400, { error: 'invalid request path' }); return; }
747	
748	  // /api/articles/:id (match the raw path first; decode only the captured id)
749	  const itemMatch = /^\/api\/articles\/([^/]+)$/.exec(route);
750	  let itemId: string | null = null;
751	  if (itemMatch) {
752	    try { itemId = decodeURIComponent(itemMatch[1]); }
753	    catch { respond(res, 400, { error: 'invalid article id encoding' }); return; }
754	  }
755	
756	  if (!['/', '/health', '/api/articles'].includes(route) && !itemMatch) {
757	    respond(res, 404, { error: 'not found' });
758	    return;
759	  }
760	
761	  if (route === '/') {
762	    if (req.method === 'GET') { respond(res, 200, PAGE, true); return; }
763	    methodNotAllowed(res, 'GET');
764	    return;
765	  }
766	  if (route === '/health') {
767	    if (req.method === 'GET') { respond(res, 200, { status: 'ok', product: PRODUCT }); return; }
768	    methodNotAllowed(res, 'GET');
769	    return;
770	  }
771	
772	  if (itemMatch && itemId !== null) {
773	    const id = itemId;
774	    if (req.method === 'GET') {
775	      const articles = readArticles();
776	      const article = articles.find((a) => a.id === id);
777	      if (!article) throw new HttpError(404, 'article not found');
778	      respond(res, 200, { article });
779	      return;
780	    }
781	    if (req.method === 'PUT') {
782	      const text = await readBody(req);
783	      const data = parseJsonObject(text);
784	      const fields = validateUpdateInput(data);
785	      const result = await enqueueWrite((): { status: number; article: Article } => {
786	        const records = readArticles();
787	        const index = records.findIndex((a) => a.id === id);
788	        if (index === -1) {
789	          throw new HttpError(404, 'article not found');
790	        }
791	        const current = records[index];
792	        if (fields.version !== current.version) {
793	          // 409 carries the currently saved article for side-by-side comparison.
794	          const conflict = new HttpError(409, 'a newer version of this article has been saved');
795	          (conflict as HttpError & { article?: Article }).article = current;
796	          throw conflict;
797	        }
798	        const updated: Article = {
799	          id: current.id,
800	          title: fields.title,
801	          summary: fields.summary,
802	          body: fields.body,
803	          status: current.status,
804	          createdAt: current.createdAt,
805	          version: current.version + 1,
806	        };
807	        records[index] = updated;
808	        writeArticles(records);
809	        return { status: 200, article: updated };
810	      });
811	      respond(res, result.status, { article: result.article });
812	      return;
813	    }
814	    methodNotAllowed(res, 'GET, PUT');
815	    return;
816	  }
817	
818	  // /api/articles
819	  if (req.method === 'GET') {
820	    respond(res, 200, { [RESOURCE]: readArticles() });
821	    return;
822	  }
823	  if (req.method === 'POST') {
824	    const text = await readBody(req);
825	    const data = parseJsonObject(text);
826	    const fields = validateDraftInput(data);
827	    const article: Article = {
828	      id: randomUUID(),
829	      title: fields.title,
830	      summary: fields.summary,
831	      body: fields.body,
832	      status: 'draft',
833	      createdAt: new Date().toISOString(),
834	      version: 1,
835	    };
836	    await enqueueWrite((): void => {
837	      const records = readArticles();
838	      records.push(article);
839	      writeArticles(records);
840	    });
841	    respond(res, 201, { article });
842	    return;
843	  }
844	  methodNotAllowed(res, 'GET, POST');
845	}
846	
847	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
848	  handle(req, res).catch((error: unknown) => {
849	    if (res.writableEnded) return;
850	    if (error instanceof HttpError) {
851	      const payload: { error: string; article?: Article } = { error: error.message };
852	      const withArticle = error as HttpError & { article?: Article };
853	      if (error.status === 409 && withArticle.article) payload.article = withArticle.article;
854	      respond(res, error.status, payload);
855	      return;
856	    }
857	    respond(res, 500, { error: error instanceof Error ? error.message : 'internal error' });
858	  });
859	});
860	server.once('error', (error: Error): void => { console.error(error.message); process.exitCode = 1; });
861	server.listen(port, host, (): void => {
862	  const address = server.address();
863	  if (address && typeof address !== 'string') {
864	    const displayedHost = address.address.includes(':') ? `[${address.address}]` : address.address;
865	    console.log(`${PRODUCT} listening on http://${displayedHost}:${address.port}`);
866	  }
867	});
868	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
869	  process.on(signal, (): void => { server.close(() => { process.exitCode = 0; }); server.closeIdleConnections(); });
870	}
