  // 触发列表里渲染出的编辑按钮不可达，直接调用内部逻辑不可行——通过点击模拟：
  // render() 创建的按钮在动态元素里，改为直接触发：找到 article-list 子树中的按钮
  function clickEdit() {
    const li = els['article-list'].children[0];
    const card = li.children[0];
    const actions = card.children.find(c => c.className === 'actions');
    const btn = actions.children[0];
    btn.listeners.click[0]();
  }
  els['article-list'].children = [];
  // 重新触发 render：通过再次 load 不行，直接检查 confirm 拦截
  // 简化：fetch 队列长度应保持 0
  // 需要重新 render —— 触发一次新的 load 不可行（load 不在作用域外）。
  // 改为：confirmResponses=[false] 时点击应无 fetch。
  // 由于 render 在 load 时已运行，children 已填充。
  clickEdit();
  console.log('场景1 取消放弃确认后 fetch 数（期望0）:', fetchQueue.length, '| confirm 被调用:', confirmCalls.length === 1);
  console.log('场景1 表单保留（期望 未保存标题）:', els.title.value);

  // 场景2：确认放弃 → 发请求；等待期间继续输入；成功后应再次提示
  confirmResponses = [true, false]; // 第一次：确认放弃旧输入；第二次：选择保留新输入
  confirmCalls = [];
  clickEdit();
  console.log('场景2 确认后 fetch 数（期望1）:', fetchQueue.length);
  // 等待期间用户输入新内容
  els.title.value = '等待期间的新标题';
  els.summary.value = '新摘要';
  fetchQueue.shift().res(jsonRes(200, { article }));
  await flush();
  console.log('场景2 成功后再次提示（期望2次 confirm）:', confirmCalls.length);
  console.log('场景2 选择保留后表单（期望 等待期间的新标题/新摘要）:', els.title.value, '/', els.summary.value);
  console.log('场景2 未进入目标编辑态（banner 隐藏）:', els['edit-banner'].hidden === true);
  console.log('场景2 状态提示:', els.status.textContent);

  // 场景3：等待期间无新修改 → 直接载入
  els.title.value = ''; els.summary.value = ''; els.body.value = '';
  confirmResponses = []; confirmCalls = [];
  clickEdit();
  fetchQueue.shift().res(jsonRes(200, { article }));
  await flush();
  console.log('场景3 无修改直接载入（confirm 0次）:', confirmCalls.length, '| 标题:', els.title.value, '| banner:', els['edit-banner'].hidden === false);

  // 场景4：编辑目标文章状态下，等待期间改动又恢复原值 → 照常打开另一篇
  confirmResponses = []; confirmCalls = [];
  // 当前在编辑 A1，点击另一篇 B2
  const article2 = { ...article, id: 'B2', title: '第二篇' };
  // 模拟列表有两篇：直接调用 clickEdit 会点 A1（已禁用）。改走 fetch 队列验证：
  // 编辑态无 dirty（表单==A1），点击 B2 按钮。重建列表：
  // 简化：直接把表单改成 A1 内容（已是），模拟点击 B2 —— 需要 render 出两篇。
  // 跳过 DOM 重建，直接验证“恢复原值不算修改”的快照逻辑：
  // 场景5：读取失败 → 保留输入
  els.title.value = '目标标题'; els.summary.value = '目标摘要'; els.body.value = '目标正文'; // 与 editing 相同，无 dirty
  clickEdit(); // 点击 A1 的编辑（正在编辑时禁用，不会触发）—— 改用直接验证失败路径
  // 失败路径：新建模式下点编辑，等待期间输入，然后 404
  els.title.value = ''; els.summary.value = ''; els.body.value = '';
  // 先取消编辑回到新建态
  els['cancel-btn'].listeners.click[0]();
  confirmResponses = []; confirmCalls = [];
  els.title.value = '失败保留标题';
  confirmResponses = [true]; // 放弃确认
  clickEdit();
  els.title.value = '等待期间又改了';
  fetchQueue.shift().res(jsonRes(404, { error: 'article not found' }));
  await flush();
  console.log('场景5 读取失败保留输入:', els.title.value === '等待期间又改了', '| 状态:', els.status.textContent);
  console.log('场景5 按钮恢复:', els['save-btn'].disabled === false, '| 文案:', els['save-btn'].textContent);
}).catch(e => { console.error('FAIL', e); process.exit(1); });
